#include "coordinator.h"
static int overlap(const void*a,unsigned n,const void*b,unsigned m){uintptr_t x=(uintptr_t)a,y=(uintptr_t)b;return x>UINTPTR_MAX-n||y>UINTPTR_MAX-m||(x<y?y-x<n:x-y<m);}
static int same(const uint8_t*a,const uint8_t*b,unsigned n){for(unsigned j=0;j<n;j++)if(a[j]!=b[j])return 0;return 1;}
static int fail(StaMgmtTx*s,unsigned n){s->phase=STX_FAULT;s->fault=(uint8_t)n;return -1;}
static int time(StaMgmtTx*s,uint64_t now){if(now<s->last)return fail(s,1);s->last=now;return 1;}
int stx_begin(StaMgmtTx*s,const StaWireBss*b,StaJoin*station,uint64_t now,uint16_t selected,uint16_t listen,unsigned backend,const uint8_t source[32]){if(!s||s->phase||!b||!station||!source||!now||now>UINT64_MAX-10000000||!listen||backend<3||backend>4||overlap(s,sizeof(*s),b,sizeof(*b))||overlap(s,sizeof(*s),station,sizeof(*station))||overlap(s,sizeof(*s),source,32)||station->epoch!=b->epoch||station->vdev!=b->vdev||!same(station->peer,b->peer,6)||!same(station->own_mac,b->own,6)||station->quarantined||station->authenticated||station->associated||b->observed_us>now||now-b->observed_us>b->ttl_us)return 0;unsigned digest=0;for(unsigned j=0;j<32;j++)digest|=source[j];uint8_t p[128];if(!digest||!sta_auth_frame(p,sizeof(p),b,0)||!sta_assoc_frame(p,sizeof(p),b,0,selected,listen))return 0;StaMgmtTx v={0};v.bss=*b;v.station=station;v.started=v.last=now;v.deadline=now+10000000;v.epoch=b->epoch;v.selected=selected;v.listen=listen;v.backend=(uint8_t)backend;v.phase=STX_AUTH;for(unsigned j=0;j<32;j++)v.peer_source[j]=source[j];*s=v;return 1;}
unsigned stx_prepare(StaMgmtTx*s,uint8_t*out,unsigned cap,uint16_t seq){if(!s||!out||s->phase==STX_FAULT||s->phase==STX_DONE||s->posted||seq>4095||overlap(out,cap,s,sizeof(*s)))return 0;if(s->prepared){if(seq!=s->sequence||cap<s->frame_bytes)return 0;for(unsigned j=0;j<s->frame_bytes;j++)out[j]=s->frame[j];return s->frame_bytes;}uint8_t p[128];unsigned n=s->step?sta_assoc_frame(p,sizeof(p),&s->bss,seq,s->selected,s->listen):sta_auth_frame(p,sizeof(p),&s->bss,seq);if(!n||cap<n)return 0;s->sequence=seq;s->frame_bytes=n;s->prepared=1;for(unsigned j=0;j<n;j++)s->frame[j]=out[j]=p[j];return n;}
int stx_posted(StaMgmtTx*s,uint32_t cookie,uint16_t id,uint32_t floor,uint64_t now){if(!s||!s->prepared||s->posted||s->phase==STX_FAULT||!cookie||floor<s->station->watermark||time(s,now)<0)return 0;if(now>=s->deadline)return fail(s,2);s->cookie=cookie;s->msdu_id=id;s->floor=floor;s->posted=1;s->phase=STX_WAIT;return 1;}
int stx_dma_closed(StaMgmtTx*s,uint32_t cookie,uint64_t now){if(!s||!s->posted||(s->phase!=STX_WAIT&&s->phase!=STX_FAULT)||s->dma_closed||cookie!=s->cookie||time(s,now)<0)return 0;s->dma_closed=1;if(now>s->deadline&&s->phase!=STX_FAULT)return fail(s,2);return 1;}
int stx_status(StaMgmtTx*s,uint64_t epoch,uint16_t id,uint32_t completion,uint32_t status,uint64_t now){if(!s||s->phase!=STX_WAIT||!s->posted||s->status_seen||epoch!=s->epoch||id!=s->msdu_id||completion<=s->floor||time(s,now)<0)return 0;s->status_seen=1;s->tx_status=status;s->tx_completion=completion;if(now>s->deadline)return fail(s,2);if(status)return fail(s,3);return 1;}
int stx_response(StaMgmtTx*s,uint64_t epoch,const QcaRxEvent*e,uint32_t frequency,uint16_t native,uint64_t now){if(!s||!e||s->phase!=STX_WAIT||!s->posted||s->response_seen||epoch!=s->epoch||e->completion<=s->floor||frequency!=s->bss.frequency||native!=s->bss.native_rates||overlap(s,sizeof(*s),e,sizeof(*e))||time(s,now)<0)return 0;StaEvent event={0};int n=sta_decode_mgmt(e,s->station->wmi_endpoint,frequency,s->bss.peer,s->bss.own,native,&event);if(n!=1||event.kind!=(s->step?STA_ASSOC:STA_AUTH))return 0;s->response=event;s->response_seen=1;if(now>s->deadline)return fail(s,2);if(event.status)return fail(s,4);return 1;}
int stx_poll(StaMgmtTx*s,uint64_t now){if(!s)return -1;if(s->phase==STX_FAULT)return -1;if(s->phase==STX_DONE)return 1;if(time(s,now)<0)return -1;if(s->station->epoch!=s->epoch||s->station->quarantined)return fail(s,5);if(s->posted&&s->dma_closed&&s->status_seen&&s->response_seen){if(!sta_observe(s->station,s->epoch,&s->response))return fail(s,6);if(s->step){s->phase=STX_DONE;return 1;}s->step=1;s->phase=STX_ASSOC;s->prepared=s->posted=s->dma_closed=s->status_seen=s->response_seen=0;s->frame_bytes=0;return 0;}if(now>=s->deadline)return fail(s,2);return 0;}
